def footer(c,d):
 c.saveState(); w,h=A4; c.setStrokeColor(GOLD); c.setLineWidth(.65); c.line(16*mm,14*mm,w-16*mm,14*mm)
 c.setFont('SP',7); c.setFillColor(GREY); c.drawString(16*mm,8*mm,'STAGEPULSE · SES MÜHENDİSLİĞİ MERKEZİ · v4.0.0'); c.drawRightString(w-16*mm,8*mm,f'Sayfa {d.page}'); c.restoreState()
def table(rows,widths):
 data=[[P(str(v),'Smallx') for v in row] for row in rows]
 t=Table(data,colWidths=widths,repeatRows=1)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),PALE),('GRID',(0,0),(-1,-1),.35,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
 return t
def lesson(n,title,goal,explain,practice,checks,case,question):
 out=[P(f'{n}. {title}','H1x'),P('<b>Öğrenme hedefi:</b> '+goal),P('Teknik anlatım','H2x'),P(explain),P('Uygulama görevi','H2x')]
 out += [P('• '+practice)]
 out += [P('Kontrol listesi','H2x')]+[P('□ '+x) for x in checks]
 out += [P('Saha vakası','H2x'),P(case),P('<b>Kendini değerlendir:</b> '+question,'Callx')]
 return out
